/** CampusCoin logo mark (coin + rising bars). */
function logoMark(int $size = 36): string
{
    return '<svg class="logo-mark" width="' . $size . '" height="' . $size . '" viewBox="0 0 48 48" aria-hidden="true" focusable="false">'
        . '<defs><linearGradient id="lgA" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#1B3A7A"/><stop offset="1" stop-color="#0B1B3A"/></linearGradient></defs>'
        . '<rect width="48" height="48" rx="14" fill="url(#lgA)"/>'
        . '<circle cx="24" cy="24" r="12.5" fill="none" stroke="#34D399" stroke-width="3.2" stroke-dasharray="62 20" stroke-linecap="round" transform="rotate(38 24 24)"/>'
        . '<rect x="19.2" y="24" width="3.2" height="6" rx="1.2" fill="#fff"/>'
        . '<rect x="24.8" y="19.5" width="3.2" height="10.5" rx="1.2" fill="#fff"/>'
        . '<rect x="30.4" y="22" width="0" height="0"/>'
        . '</svg>';
}

/** Logo mark + wordmark. */
function logoFull(string $theme = 'dark', int $size = 36): string
{
    return '<span class="logo logo-' . e($theme) . '">' . logoMark($size)
        . '<span class="logo-word">Campus<span>Coin</span></span></span>';
}
